count=result.match(/class="count">\(共(\d+)条\)/)[1];
page=parseInt(count/10);
for(i=0;i<page;i++){
list.push(baseUrl+'&start='+(i*10))
}}}else{
if(result.match(/data-total-page="([^"]+)">/)){
p=result.match(/data-total-page="([^"]+)">/)[1];
page=20;
if(p<page){
page=p
}
for(i=1;i<=page;i++){
list.push(baseUrl+'?start='+((i-1)*20))
}}}}
list

ruleBookInfo.init:
@js:
(function(){
    let doc = org.jsoup.Jsoup.parse(result)
    let og = (selector) => doc.select('[property="og:' + selector + '"]').attr('content')
    return {
        name: og('novel:book_name'),
        author: og('novel:author'),
        kind: og('novel:category')
        +'•'+og('novel:status')
      +'•'+String(og('novel:update_time')),
        latest: og('novel:latest_chapter_name'),
        cover: og('image'),
        intro: og('description'),
        url:og('novel:read_url')
    }
})()

